namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string CourseNumber { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory programming. She holds a PhD from MIT and has published extensively on CS education.", IsFeatured = true },
        new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "TTh 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and competitive programming. Previously a software engineer at Google.", IsFeatured = true },
        new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction management, and introduction to NoSQL databases.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked in database engineering at Oracle for a decade before joining academia. Her research focuses on distributed systems." },
        new() { Id = 4, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "450", Title = "Machine Learning", Description = "Supervised and unsupervised learning, neural networks, decision trees, and practical applications using real-world datasets.", Credits = 3, Schedule = "TTh 2:00–3:15 PM", InstructorName = "Dr. Alex Rivera", InstructorBio = "Dr. Rivera leads the university AI research lab with a focus on applied machine learning in healthcare." },
        new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "MWF 8:00–8:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator with a passion for making calculus accessible to all students.", IsFeatured = true },
        new() { Id = 6, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "201", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to computer graphics and data science.", Credits = 3, Schedule = "TTh 9:00–10:15 AM", InstructorName = "Dr. Emily Zhao", InstructorBio = "Dr. Zhao's research spans algebraic topology and applied linear algebra. She consults for aerospace companies on computational geometry." },
        new() { Id = 7, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", InstructorName = "Dr. David Okafor", InstructorBio = "Dr. Okafor brings industry experience from actuarial science and focuses on statistical applications in finance." },
        new() { Id = 8, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.", Credits = 4, Schedule = "MWF 10:00–10:50 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. Aisha Patel", InstructorBio = "Dr. Patel is an experimental physicist whose research focuses on quantum optics and photonics.", IsFeatured = true },
        new() { Id = 9, DepartmentId = 3, DepartmentCode = "PHYS", CourseNumber = "201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "TTh 1:00–2:15 PM + Lab Fri 1:00–3:50 PM", InstructorName = "Dr. Thomas Berg", InstructorBio = "Dr. Berg has contributed to CERN research projects and specializes in particle physics instrumentation." },
        new() { Id = 10, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "110", Title = "College Writing", Description = "Develop critical reading and writing skills through essays, research papers, and peer workshops.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", InstructorName = "Prof. Laura White", InstructorBio = "Prof. White is a published author and writing coach with expertise in rhetoric and composition pedagogy." },
        new() { Id = 11, DepartmentId = 4, DepartmentCode = "ENG", CourseNumber = "250", Title = "American Literature", Description = "Survey of major American literary works from the colonial period to the present day.", Credits = 3, Schedule = "TTh 11:00 AM–12:15 PM", InstructorName = "Dr. Marcus Brown", InstructorBio = "Dr. Brown is a specialist in 20th-century American fiction and has written two books on the Harlem Renaissance." },
        new() { Id = 12, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "101", Title = "World Civilizations", Description = "A global survey of human history from ancient civilizations through the modern era.", Credits = 3, Schedule = "MWF 2:00–2:50 PM", InstructorName = "Dr. Fatima Hassan", InstructorBio = "Dr. Hassan is a historian of the ancient Mediterranean and Near East with fieldwork experience in archaeological sites across Turkey and Egypt.", IsFeatured = true },
        new() { Id = 13, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "215", Title = "Modern European History", Description = "Europe from the Enlightenment through the 21st century, covering revolutions, world wars, and integration.", Credits = 3, Schedule = "TTh 3:30–4:45 PM", InstructorName = "Dr. Klaus Weber", InstructorBio = "Dr. Weber is a German-born historian specializing in Cold War Europe and transatlantic relations." },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.DepartmentCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0;
    }
}

